<?php
require_once '../includes/db.php';require_once '../includes/config.php';require_once '../includes/auth_check.php';require_once '../includes/functions.php';require_once '../includes/csrf.php';require_once '../includes/action_requests.php';
requireTeacherOrAdmin();$user_id=currentUserId();$isAdmin=currentUserRole()==='admin';$error='';
$success=$_SESSION['request_success']??'';unset($_SESSION['request_success']);
if($_SERVER['REQUEST_METHOD']==='POST'){
    foreach($_POST as $value){if(!is_string($value)){http_response_code(400);exit('Form tidak valid.');}}
    checkCsrfToken();
    try{
        if($isAdmin){decideClassRequest($pdo,$user_id,(int)($_POST['id']??0),(string)($_POST['action']??''),trim((string)($_POST['tanggapan']??'')));}
        elseif(($_POST['action']??'')==='create'){submitClassRequest($pdo,$user_id,$_POST);}
        else{http_response_code(403);exit('Akses ditolak.');}
        $_SESSION['request_success']=$isAdmin?(($_POST['action']??'')==='approve'?'Rombel disetujui dan tersedia di daftar kelas serta penugasan guru.':'Pengajuan ditolak. Tanggapan dapat dilihat guru pengaju.'):'Pengajuan terkirim. Admin akan meninjau permintaan Anda.';
        header('Location: pengajuan_rombel.php?status=all');exit;
    }catch(InvalidArgumentException $e){$error=$e->getMessage();}
    catch(PDOException $e){error_log($e->getMessage());$error='Pengajuan belum dapat disimpan. Periksa apakah permintaan yang sama sudah terdaftar.';}
}
$status=$_GET['status']??($isAdmin?'pending':'all');if(!in_array($status,['all','pending','approved','rejected'],true))$status='all';
$sql='SELECT r.*,u.nama_lengkap,mp.nama_mapel FROM pengajuan_rombel r JOIN users u ON u.id=r.guru_id LEFT JOIN guru_mapel gm ON gm.id=r.sumber_guru_mapel_id LEFT JOIN mata_pelajaran mp ON mp.id=gm.mapel_id WHERE 1=1';$params=[];
if(!$isAdmin){$sql.=' AND r.guru_id=?';$params[]=$user_id;}if($status!=='all'){$sql.=' AND r.status=?';$params[]=$status;}
$q=$pdo->prepare($sql.' ORDER BY r.created_at DESC,r.id DESC');$q->execute($params);$pager=uiPaginate($q->fetchAll(),5);
$q=$pdo->prepare('SELECT gm.id,mp.nama_mapel,k.nama_kelas FROM guru_mapel gm JOIN mata_pelajaran mp ON mp.id=gm.mapel_id JOIN kelas k ON k.id=gm.kelas_id WHERE gm.guru_id=? AND gm.is_active=1 ORDER BY mp.nama_mapel,k.nama_kelas');$q->execute([$user_id]);$sources=$q->fetchAll();
$uiTitle='Pengajuan Rombel';$uiPage='view-requests';require '../includes/ui_head.php';
?>
<main class="ui-container teacher-container"><section class="ui-page-heading"><div><span class="eyebrow teal">MANAJEMEN KELAS</span><h1>Pengajuan Rombel Baru</h1><p><?= $isAdmin?'Tinjau pengajuan guru sebelum menambahkan kelas dan penugasan.':'Ajukan rombel baru dan pantau keputusan administrator sekolah.' ?></p></div><a class="ui-button white" href="<?= $isAdmin?'admin.php':'guru_kelas.php' ?>"><?= uiIcon('chevron-left',17) ?> Kembali</a></section>
<?php if($error||$success): ?><p class="ui-feedback" role="status"><?= e($error?:$success) ?></p><?php endif; ?>
<?php if(!$isAdmin): ?><section class="ui-card request-form-panel"><h2>Form Pengajuan</h2><form method="post" class="ui-form"><?= csrfField() ?><input type="hidden" name="action" value="create"><label>Mata pelajaran yang diampu<select name="sumber_guru_mapel_id" required><option value="">Pilih mata pelajaran</option><?php foreach($sources as $source): ?><option value="<?= (int)$source['id'] ?>"><?= e($source['nama_mapel'].' / '.$source['nama_kelas']) ?></option><?php endforeach; ?></select></label><label>Nama rombel baru<input name="nama_kelas" maxlength="50" placeholder="Contoh: XI MIPA 4" required></label><div class="request-fields"><label>Tingkat<select name="tingkat" required><option value="10">X</option><option value="11" selected>XI</option><option value="12">XII</option></select></label><label>Jurusan<input name="jurusan" maxlength="50" placeholder="MIPA"></label><label>Tahun ajaran<input name="tahun_ajaran" value="<?= e(TAHUN_AJARAN_AKTIF) ?>" pattern="[0-9]{4}/[0-9]{4}" required></label></div><label>Alasan pengajuan<textarea name="alasan" minlength="10" maxlength="2000" rows="3" required></textarea></label><button class="ui-button primary">Kirim Pengajuan</button></form></section><?php endif; ?>
<div class="ui-toolbar"><nav class="ui-segmented"><?php foreach(['all'=>'Semua','pending'=>'Menunggu','approved'=>'Disetujui','rejected'=>'Ditolak'] as $key=>$label): ?><a class="<?= $status===$key?'active':'' ?>" href="<?= uiQuery(['status'=>$key,'page'=>1]) ?>"><?= $label ?></a><?php endforeach; ?></nav></div>
<section class="request-list"><?php foreach($pager['items'] as $request): ?><article class="ui-card request-item"><div class="section-heading"><div><h2><?= e($request['nama_kelas']) ?></h2><p><?= e($request['nama_lengkap'].' / '.($request['nama_mapel']??'Penugasan tidak tersedia').' / '.$request['tahun_ajaran']) ?></p></div><span class="ui-badge <?= $request['status']==='approved'?'aqua':'blue' ?>"><?= e(['pending'=>'Menunggu','approved'=>'Disetujui','rejected'=>'Ditolak'][$request['status']]) ?></span></div><p class="request-message"><?= nl2br(e($request['alasan'])) ?></p><small>Diajukan <?= e(formatTanggalIndo($request['created_at'],'d M Y H:i')) ?></small><?php if($request['tanggapan']): ?><p class="request-response"><strong>Tanggapan admin:</strong> <?= nl2br(e($request['tanggapan'])) ?></p><?php endif; ?>
<?php if($isAdmin&&$request['status']==='pending'): ?><form method="post" class="ui-form"><?= csrfField() ?><input type="hidden" name="id" value="<?= (int)$request['id'] ?>"><label>Tanggapan<textarea name="tanggapan" maxlength="2000" rows="2" placeholder="Wajib diisi jika pengajuan ditolak"></textarea></label><div class="summary-actions"><button name="action" value="approve" class="ui-button primary">Setujui & Buat Rombel</button><button name="action" value="reject" class="ui-button white">Tolak Pengajuan</button></div></form><?php elseif(!$isAdmin&&$request['status']==='approved'&&$request['guru_mapel_id']): ?><a class="ui-button soft small" href="guru_materi.php?guru_mapel_id=<?= (int)$request['guru_mapel_id'] ?>">Kelola Materi Rombel <?= uiIcon('arrow',16) ?></a><?php endif; ?></article><?php endforeach; ?><?php if(!$pager['items'])uiEmpty('Tidak Ada Pengajuan','Pengajuan sesuai filter akan tampil di sini.'); ?></section>
<?php uiPagination($pager['page'],$pager['pages'],$pager['total'],'pengajuan'); ?></main><?php require '../includes/ui_end.php'; ?>
